-fn looks_like_executable_header(bytes: &[u8]) -> bool {
-    // Shebang scripts (shell launch wrappers).
-    if bytes.starts_with(b"#!") {
-        return true;
-    }
-    // ELF: magic + class + e_type (ET_EXEC / ET_DYN). Rejects truncated
-    // downloads that only retain the 4-byte magic prefix.
-    if bytes.len() >= 18 && bytes[0..4] == [0x7f, b'E', b'L', b'F'] {
-        let class = bytes[4]; // 1 = ELFCLASS32, 2 = ELFCLASS64
-        if class != 1 && class != 2 {
-            return false;
-        }
-        // e_type at offset 16; EI_DATA (bytes[5]) selects byte order.
-        let e_type = match bytes[5] {
-            1 => u16::from_le_bytes([bytes[16], bytes[17]]), // ELFDATA2LSB
-            2 => u16::from_be_bytes([bytes[16], bytes[17]]), // ELFDATA2MSB
-            _ => return false,
-        };
-        const ET_EXEC: u16 = 2;
-        const ET_DYN: u16 = 3;
-        return e_type == ET_EXEC || e_type == ET_DYN;
-    }
-    false
-}
